B.bdU=s(["    CREATE TABLE IF NOT EXISTS business_settings (\n      id INTEGER PRIMARY KEY,\n      business_name TEXT NOT NULL,\n      owner_name TEXT,\n      phone TEXT,\n      address TEXT,\n      city TEXT,\n      ntn_strn TEXT,\n      invoice_prefix TEXT DEFAULT 'INV-',\n      purchase_prefix TEXT DEFAULT 'PUR-',\n      currency_symbol TEXT DEFAULT '\u20a8',\n      pin_code TEXT,\n      is_pin_enabled INTEGER DEFAULT 0,\n      initial_cash_balance REAL DEFAULT 0,\n      updated_at TEXT NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS products (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      name TEXT NOT NULL,\n      sku TEXT UNIQUE,\n      category TEXT NOT NULL,\n      brand TEXT NOT NULL,\n      bag_size TEXT,\n      unit TEXT NOT NULL,\n      purchase_price REAL NOT NULL,\n      selling_price REAL NOT NULL,\n      opening_stock REAL NOT NULL DEFAULT 0,\n      current_stock REAL NOT NULL DEFAULT 0,\n      min_stock_alert REAL NOT NULL DEFAULT 10,\n      notes TEXT,\n      is_active INTEGER NOT NULL DEFAULT 1,\n      created_at TEXT NOT NULL,\n      updated_at TEXT NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS stock_cost_layers (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,\n      purchase_id INTEGER,\n      purchase_date TEXT NOT NULL,\n      unit_cost REAL NOT NULL,\n      original_quantity REAL NOT NULL,\n      remaining_quantity REAL NOT NULL,\n      created_at TEXT NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS customers (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      name TEXT NOT NULL,\n      phone TEXT,\n      village_or_address TEXT,\n      opening_balance REAL NOT NULL DEFAULT 0,\n      current_balance REAL NOT NULL DEFAULT 0,\n      credit_limit REAL NOT NULL DEFAULT 0,\n      notes TEXT,\n      is_active INTEGER NOT NULL DEFAULT 1,\n      created_at TEXT NOT NULL,\n      updated_at TEXT NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS suppliers (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      name TEXT NOT NULL,\n      phone TEXT,\n      company_or_address TEXT,\n      opening_balance REAL NOT NULL DEFAULT 0,\n      current_balance REAL NOT NULL DEFAULT 0,\n      notes TEXT,\n      is_active INTEGER NOT NULL DEFAULT 1,\n      created_at TEXT NOT NULL,\n      updated_at TEXT NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS purchases (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      invoice_number TEXT UNIQUE NOT NULL,\n      supplier_id INTEGER NOT NULL REFERENCES suppliers(id),\n      supplier_name TEXT NOT NULL,\n      purchase_date TEXT NOT NULL,\n      subtotal REAL NOT NULL,\n      discount REAL NOT NULL DEFAULT 0,\n      freight_charges REAL NOT NULL DEFAULT 0,\n      grand_total REAL NOT NULL,\n      paid_amount REAL NOT NULL DEFAULT 0,\n      balance_due REAL NOT NULL DEFAULT 0,\n      payment_status TEXT NOT NULL,\n      payment_method TEXT,\n      notes TEXT,\n      is_reversed INTEGER NOT NULL DEFAULT 0,\n      created_at TEXT NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS purchase_items (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      purchase_id INTEGER NOT NULL REFERENCES purchases(id) ON DELETE CASCADE,\n      product_id INTEGER NOT NULL REFERENCES products(id),\n      product_name TEXT NOT NULL,\n      unit TEXT NOT NULL,\n      quantity REAL NOT NULL,\n      unit_price REAL NOT NULL,\n      total_price REAL NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS sales (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      invoice_number TEXT UNIQUE NOT NULL,\n      customer_id INTEGER,\n      customer_name TEXT NOT NULL,\n      sale_date TEXT NOT NULL,\n      subtotal REAL NOT NULL,\n      discount REAL NOT NULL DEFAULT 0,\n      grand_total REAL NOT NULL,\n      paid_amount REAL NOT NULL DEFAULT 0,\n      balance_due REAL NOT NULL DEFAULT 0,\n      total_cost REAL NOT NULL DEFAULT 0,\n      gross_profit REAL NOT NULL DEFAULT 0,\n      payment_status TEXT NOT NULL,\n      payment_method TEXT NOT NULL,\n      notes TEXT,\n      is_reversed INTEGER NOT NULL DEFAULT 0,\n      created_at TEXT NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS sale_items (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      sale_id INTEGER NOT NULL REFERENCES sales(id) ON DELETE CASCADE,\n      product_id INTEGER NOT NULL REFERENCES products(id),\n      product_name TEXT NOT NULL,\n      unit TEXT NOT NULL,\n      quantity REAL NOT NULL,\n      unit_price REAL NOT NULL,\n      unit_cost REAL NOT NULL DEFAULT 0,\n      total_price REAL NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS payments (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      payment_type TEXT NOT NULL,\n      party_type TEXT NOT NULL,\n      party_id INTEGER NOT NULL,\n      party_name TEXT NOT NULL,\n      reference_invoice_id INTEGER,\n      reference_invoice_number TEXT,\n      amount REAL NOT NULL,\n      payment_date TEXT NOT NULL,\n      payment_method TEXT NOT NULL,\n      reference_number TEXT,\n      notes TEXT,\n      created_at TEXT NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS expenses (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      category TEXT NOT NULL,\n      amount REAL NOT NULL,\n      expense_date TEXT NOT NULL,\n      payment_method TEXT NOT NULL DEFAULT 'Cash',\n      title TEXT NOT NULL,\n      notes TEXT,\n      created_at TEXT NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS stock_movements (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      product_id INTEGER NOT NULL REFERENCES products(id),\n      product_name TEXT NOT NULL,\n      movement_type TEXT NOT NULL,\n      quantity REAL NOT NULL,\n      balance_after REAL NOT NULL,\n      reference_id INTEGER,\n      reference_type TEXT,\n      notes TEXT,\n      movement_date TEXT NOT NULL,\n      created_at TEXT NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS customer_ledger (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      customer_id INTEGER NOT NULL REFERENCES customers(id),\n      transaction_date TEXT NOT NULL,\n      transaction_type TEXT NOT NULL,\n      reference_id INTEGER,\n      reference_number TEXT,\n      description TEXT NOT NULL,\n      debit REAL NOT NULL DEFAULT 0,\n      credit REAL NOT NULL DEFAULT 0,\n      running_balance REAL NOT NULL,\n      created_at TEXT NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS supplier_ledger (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      supplier_id INTEGER NOT NULL REFERENCES suppliers(id),\n      transaction_date TEXT NOT NULL,\n      transaction_type TEXT NOT NULL,\n      reference_id INTEGER,\n      reference_number TEXT,\n      description TEXT NOT NULL,\n      debit REAL NOT NULL DEFAULT 0,\n      credit REAL NOT NULL DEFAULT 0,\n      running_balance REAL NOT NULL,\n      created_at TEXT NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS returns (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      return_type TEXT NOT NULL,\n      original_invoice_id INTEGER NOT NULL,\n      original_invoice_number TEXT NOT NULL,\n      party_id INTEGER NOT NULL,\n      party_name TEXT NOT NULL,\n      return_date TEXT NOT NULL,\n      product_id INTEGER NOT NULL,\n      product_name TEXT NOT NULL,\n      quantity REAL NOT NULL,\n      unit_price REAL NOT NULL,\n      total_amount REAL NOT NULL,\n      refund_type TEXT NOT NULL,\n      reason TEXT,\n      created_at TEXT NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS storages (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      name TEXT NOT NULL,\n      code TEXT,\n      location TEXT,\n      incharge_name TEXT,\n      contact_number TEXT,\n      capacity_bags INTEGER DEFAULT 0,\n      is_default INTEGER DEFAULT 0,\n      is_active INTEGER NOT NULL DEFAULT 1,\n      created_at TEXT NOT NULL,\n      updated_at TEXT NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS storage_stocks (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      storage_id INTEGER NOT NULL REFERENCES storages(id) ON DELETE CASCADE,\n      product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,\n      quantity REAL NOT NULL DEFAULT 0,\n      updated_at TEXT NOT NULL,\n      UNIQUE(storage_id, product_id)\n    );\n    ","    CREATE TABLE IF NOT EXISTS stock_transfers (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      transfer_number TEXT UNIQUE NOT NULL,\n      from_storage_id INTEGER NOT NULL REFERENCES storages(id),\n      to_storage_id INTEGER NOT NULL REFERENCES storages(id),\n      product_id INTEGER NOT NULL REFERENCES products(id),\n      quantity REAL NOT NULL,\n      transfer_date TEXT NOT NULL,\n      vehicle_number TEXT,\n      driver_name TEXT,\n      notes TEXT,\n      created_at TEXT NOT NULL\n    );\n    "],t.s)
